.mod { height:100%;background:var(--bg);color:var(--ink);overflow:hidden; display:flex;flex-direction:column;border:1px solid #3a3736; }
.tabbar { height:78px;flex:none;position:relative;display:grid; grid-template-columns:1fr 1fr 84px 1fr 1fr;align-items:center; border-top:1px solid var(--shell-line);background:var(--shell-chrome); }
.tab { display:flex;flex-direction:column;align-items:center;gap:5px; font-size:9.5px;color:var(--shell-soft);text-align:center; }
.home { height:20px;flex:none;display:grid;place-items:center;background:var(--shell-chrome); }
.home i { display:block;width:120px;height:4px;border-radius:2px;background:#3c3c44; }
